import java.io.Reader; 
import java.io.IOException; 

public class ReaderUtil { 
    public ReaderUtil() { 
    } 

    /** 
     * Dumps the contents of the {@link Reader} to a 
     * String, closing the {@link Reader} when done. 
     */ 
    public String readToString(Reader in) throws IOException { 
        StringBuffer buf = new StringBuffer(); 
        try { 
            for(int c = in.read(); c != -1; c = in.read()) { 
                buf.append((char)c); 
            } 
            return buf.toString(); 
        } catch(IOException e) { 
            throw e; 
        } finally { 
            try { 
                in.close(); 
            } catch(Exception e) { 
                // ignored 
            } 
        } 
    } 
}

import java.io.IOException;
import java.io.Reader;
import org.apache.commons.pool3.ObjectPool;

public class ReaderUtil {

    private ObjectPool<StringBuffer, ? extends Exception> pool;

    public ReaderUtil(ObjectPool<StringBuffer, ? extends Exception> pool) {
        this.pool = pool;
    }

    /**
     * Dumps the contents of the {@link Reader} to a String, closing the {@link Reader} when done.
     */
    public String readToString(Reader in)
        throws IOException {
        StringBuffer buf = null;
        try {
            buf = pool.borrowObject();
            for (int c = in.read(); c != -1; c = in.read()) {
                buf.append((char) c);
            }
            return buf.toString();
        } catch (IOException e) {
            throw e;
        } catch (Exception e) {
            throw new RuntimeException("Unable to borrow buffer from pool" + e.toString());
        } finally {
            try {
                in.close();
            } catch (Exception e) {
                // ignored
            }
            try {
                if (null != buf) {
                    pool.returnObject(buf);
                }
            } catch (Exception e) {
                // ignored
            }
        }
    }
}

import org.apache.commons.pool3.BasePooledObjectFactory;
import org.apache.commons.pool3.PooledObject;
import org.apache.commons.pool3.impl.DefaultPooledObject;

public class StringBufferFactory
    extends BasePooledObjectFactory<StringBuffer, RuntimeException> {

    @Override
    public StringBuffer create() {
        return new StringBuffer();
    }

    /**
     * Use the default PooledObject implementation.
     */
    @Override
    public PooledObject<StringBuffer> wrap(StringBuffer buffer) {
        return new DefaultPooledObject<StringBuffer>(buffer);
    }

    /**
     * When an object is returned to the pool, clear the buffer.
     */
    @Override
    public void passivateObject(PooledObject<StringBuffer> pooledObject) {
        pooledObject.getObject().setLength(0);
    }

    // for all other methods, the no-op implementation
    // in BasePooledObjectFactory will suffice
}

import org.apache.commons.pool3.BaseKeyedPooledObjectFactory;
import org.apache.commons.pool3.PooledObject;
import org.apache.commons.pool3.impl.DefaultPooledObject;

public class KeyedStringBufferFactory
    extends BaseKeyedPooledObjectFactory<Integer, StringBuffer, RuntimeException> {

    @Override
    public StringBuffer create(Integer initialCapacity) {
        return new StringBuffer(initialCapacity);
    }

    /**
     * Use the default PooledObject implementation.
     */
    @Override
    public PooledObject<StringBuffer> wrap(StringBuffer buffer) {
        return new DefaultPooledObject<StringBuffer>(buffer);
    }

    /**
     * When an object is returned to the pool, clear the buffer.
     */
    @Override
    public void passivateObject(Integer key, PooledObject<StringBuffer> pooledObject) {
        pooledObject.getObject().setLength(0);
    }

    // for all other methods, the no-op implementation
    // in BaseKeyedPooledObjectFactory will suffice
}

import java.io.IOException;
import java.io.Reader;
import org.apache.commons.pool3.KeyedObjectPool;

public class KeyedStringBufferUtil {

    private KeyedObjectPool<Integer, StringBuffer, ? extends Exception> pool;

    public KeyedStringBufferUtil(KeyedObjectPool<Integer, StringBuffer, ? extends Exception> pool) {
        this.pool = pool;
    }

    /**
     * Dumps the contents of the {@link Reader} to a String, using a StringBuffer
     * with the specified initial capacity, closing the {@link Reader} when done.
     */
    public String readToString(Reader in, int initialCapacity)
        throws IOException {
        StringBuffer buf = null;
        try {
            buf = pool.borrowObject(initialCapacity);
            for (int c = in.read(); c != -1; c = in.read()) {
                buf.append((char) c);
            }
            return buf.toString();
        } catch (IOException e) {
            throw e;
        } catch (Exception e) {
            throw new RuntimeException("Unable to borrow buffer from pool" + e.toString());
        } finally {
            try {
                in.close();
            } catch (Exception e) {
                // ignored
            }
            try {
                if (null != buf) {
                    pool.returnObject(initialCapacity, buf);
                }
            } catch (Exception e) {
                // ignored
            }
        }
    }
}

KeyedStringBufferUtil keyedUtil = new KeyedStringBufferUtil(
    new GenericKeyedObjectPool(new KeyedStringBufferFactory())
);

// Use small capacity for short string
Reader shortReader = new StringReader("Hello World!");
System.out.println("Short string: " + keyedUtil.readToString(shortReader, 16));

// Use large capacity for longer string
Reader longReader = new StringReader("This is a much longer string that benefits from a larger initial capacity.");
System.out.println("Long string: " + keyedUtil.readToString(longReader, 128));
